    if(!record.focusId||!bindMessageFocus(record.key)||messageFocus.applied)return;
    const current=()=>ticket===record.focusTicket&&live(record)&&!messageFocus.blocked&&!messageFocus.applied&&messageFocus.key===record.key;
    const reveal=()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{
      if(!current())return;const item=record.host.querySelector('[data-bill-id="'+record.focusId+'"]');if(!item)return;
      // 初始视图恢复在下一帧重置滚动，随后定位，避免被它移回页面顶部。
      for(let ancestor=item.parentElement;ancestor;ancestor=ancestor.parentElement){if(ancestor.tagName==='DETAILS')ancestor.open=true;if(ancestor.id==='accountSplitCard')break;}
      saveMessageFocus();item.tabIndex=-1;item.focus({preventScroll:true});item.scrollIntoView({block:'center',behavior:'auto'});messageFocus.applied=true;
    }));
    if(document.documentElement.classList.contains('navren-private-locked')){
      const observer=new MutationObserver(()=>{if(!current()){observer.disconnect();if(record.focusObserver===observer)record.focusObserver=null;return;}if(!document.documentElement.classList.contains('navren-private-locked')){observer.disconnect();if(record.focusObserver===observer)record.focusObserver=null;reveal();}});
      record.focusObserver=observer;observer.observe(document.documentElement,{attributes:true,attributeFilter:['class']});
    }else reveal();
